            m.m03 = -2f * n.x * n.w;
            m.m10 = -2f * n.x * n.y;
            m.m11 = 1f - 2f * n.y * n.y;
            m.m12 = -2f * n.y * n.z;
            m.m13 = -2f * n.y * n.w;
            m.m20 = -2f * n.x * n.z;
            m.m21 = -2f * n.y * n.z;
            m.m22 = 1f - 2f * n.z * n.z;
            m.m23 = -2f * n.z * n.w;
